/// Every CE case of the §9b table is executed by the engine run, at every
/// entering condition the map tabulates.
#[test]
fn test_section9b_covers_every_ce_case() {
    let cases = load_section9b_cases();
    let live = build_results();
    let rows = live["cases"].as_array().expect("cases array");
    assert_eq!(
        rows.len(),
        cases.len(),
        "every §9b CE case must be exercised"
    );
    assert_eq!(rows.len(), 14, "the §9 CE family is CE100–CE200 (14 cases)");

    let case_ids: Vec<&str> = cases
        .iter()
        .map(|c| c["case_id"].as_str().expect("case_id"))
        .collect();
    for id in &case_ids {
        assert!(
            rows.iter().any(|r| r["case_id"] == *id),
            "case {id} missing from the §9b engine run"
        );
    }

    // The §9b table and the §9a case table must cover the same family.
    let section9_ids: Vec<String> = load_section9_cases()
        .iter()
        .map(|c| c["case_id"].as_str().expect("case_id").to_string())
        .collect();
    for id in &case_ids {
        assert!(
            section9_ids.iter().any(|s| s == id),
            "§9b case {id} has no §9a case definition to execute"
        );
    }

    // Each case is dispatched at every tabulated entering wet-bulb.
    let ewbs = map_ewb_columns();
    assert_eq!(ewbs.len(), 4, "the map tabulates four EWB columns");
    for row in rows {
        let runs = row["runs"].as_array().expect("runs array");
        assert_eq!(
            runs.len(),
            ewbs.len(),
            "case {} was not dispatched at every tabulated entering condition",
            row["case_id"]
        );
        for (run, ewb) in runs.iter().zip(ewbs.iter()) {
            assert!(
                (run["entering_wet_bulb_C"].as_f64().expect("ewb") - ewb).abs() < 1e-9,
                "case {} dispatched at an unexpected entering condition",
                row["case_id"]
            );
        }
    }
}

/// The §9b execution is deterministic: two independent runs produce
/// byte-identical results.
#[test]
fn test_section9b_is_deterministic() {
    let first = build_results();
    let second = build_results();
    assert_eq!(
        serde_json::to_string(&first).expect("serialize"),
        serde_json::to_string(&second).expect("serialize"),
        "the §9b comparative execution must be deterministic"
    );
}

/// The recorded results file matches the live engine run — every recorded
/// number is re-measured, so a known-fail row cannot go stale silently.
#[test]
fn test_section9b_recorded_results_match_live_engine_run() {
    let live = build_results();
    if let Ok(path) = std::env::var(WRITE_RESULTS_ENV) {
        let text = serde_json::to_string_pretty(&live).expect("serialize") + "\n";
        std::fs::write(&path, text).expect("write §9b engine-run results");
        println!("re-recorded §9b engine-run results to {path}");
        return;
    }
    let recorded: Value = serde_json::from_str(SECTION9B_RESULTS_JSON)
        .expect("parse recorded §9b engine-run results");
    let diffs = json_diff(&live, &recorded, "results");
    assert!(
        diffs.is_empty(),
        "recorded §9b engine-run results differ from the live run (re-record with \
         FLUXION_SECTION9B_WRITE_RESULTS):\n  {}",
        diffs.join("\n  ")
    );
}

/// Every band row carries the committed comparative label and the band's
/// source — the ranges are evidence, never a pass/fail criterion.
#[test]
fn test_section9b_bands_are_labelled_evidence_ranges() {
    let live = build_results();
    for row in live["cases"].as_array().expect("cases array") {
        let case_id = row["case_id"].as_str().expect("case_id");
        for band in row["bands"].as_array().expect("bands array") {
            let kind = band["band_kind"].as_str().expect("band_kind");
            assert_eq!(
                kind, BAND_KIND,
                "case {case_id}: band kind must be the committed label"
            );
            let source = band["band_source"].as_str().expect("band_source");
            assert!(
                !source.trim().is_empty(),
                "case {case_id}: band row has no source"
            );
            let low = band["band_low"].as_f64().expect("band low");
            let high = band["band_high"].as_f64().expect("band high");
            assert!(
                low < high,
                "case {case_id}: band edges must be a real range"
            );
            assert!(
                band["band_low_si"].as_f64().is_some() && band["band_high_si"].as_f64().is_some(),
                "case {case_id}: band row must carry its SI edges"
            );
        }
    }
}

/// The nine banded cases are scored, with an explicit in/out status on every
/// scored row; failures are recorded as known-fail rows and never omitted.
#[test]
fn test_section9b_banded_cases_are_scored() {
    let cases = load_section9b_cases();
    let live = build_results();
    let rows = live["cases"].as_array().expect("cases array");
    let mut banded = 0_u32;
    let mut scored = 0_u32;
    let mut scored_cases = 0_u32;
    for case in &cases {
        let case_id = case["case_id"].as_str().expect("case_id");
        let expected = case["bands"].as_array().expect("bands array").len();
        let row = rows
            .iter()
            .find(|r| r["case_id"] == case_id)
            .expect("case row");
        let bands = row["bands"].as_array().expect("bands array");
        assert_eq!(
            bands.len(),
            expected,
            "case {case_id}: every committed §9b band must be accounted for"
        );
        if expected > 0 {
            banded += 1;
            assert_eq!(
                row["status"].as_str(),
                Some("scored"),
                "case {case_id} carries bands and must be scored"
            );
        }
        let mut case_scored = false;
        for band in bands {
            let status = band["status"].as_str().expect("status");
            match status {
                "pass" | "known_fail" => {
                    scored += 1;
                    case_scored = true;
                    let value = band["engine_value"].as_f64().expect("engine value");
                    assert!(value.is_finite(), "case {case_id}: non-finite engine value");
                    let low = band["band_low"].as_f64().expect("band low");
                    let high = band["band_high"].as_f64().expect("band high");
                    let gap = band["gap_pct_of_mid"].as_f64().expect("gap");
                    if status == "pass" {
                        assert!(
                            value >= low && value <= high,
                            "case {case_id}: a pass row must sit inside the band"
                        );
                        assert!(gap.abs() < 1e-9, "case {case_id}: pass row must have gap 0");
                    } else {
                        assert!(
                            value < low || value > high,
                            "case {case_id}: a known_fail row must sit outside the band"
                        );
                        assert!(
                            gap > 0.0,
                            "case {case_id}: a known_fail row must carry a positive gap"
                        );
                    }
                }
                "not_reproducible" => {
                    scored += 1;
                    let reason = band["reason"].as_str().expect("reason");
                    assert!(
                        reason.len() > 40,
                        "case {case_id}: a not-reproducible row must say why"
                    );
                    assert!(
                        band["engine_value"].is_null(),
                        "case {case_id}: a not-reproducible row must not carry an engine value"
                    );
                }
                other => panic!("case {case_id}: unexpected band status {other}"),
            }
        }
        if case_scored {
            scored_cases += 1;
        }
    }
    assert_eq!(
        banded, 9,
        "the bounds file covers nine of the fourteen CE cases"
    );
    assert_eq!(
        scored_cases, 9,
        "every banded case must contribute an explicitly scored (in/out) row"
    );
    assert!(
        scored >= scored_cases,
        "every scored band row must be accounted for"
    );
}

/// The five unbanded cases stay explicitly unbanded: no band, no engine
/// verdict, and the §9b table's missing-band note carried verbatim.
#[test]
fn test_section9b_unbanded_cases_carry_missing_band_notes() {
    let live = build_results();
    let rows = live["cases"].as_array().expect("cases array");
    for case_id in UNBANDED_CASES {
        let row = rows
            .iter()
            .find(|r| r["case_id"] == case_id)
            .unwrap_or_else(|| panic!("case {case_id} missing from the §9b run"));
        assert_eq!(
            row["banded"].as_bool(),
            Some(false),
            "case {case_id} must stay unbanded"
        );
        assert_eq!(
            row["status"].as_str(),
            Some("no_band"),
            "case {case_id} has no band and must be recorded as no_band"
        );
        assert!(
            row["bands"].as_array().expect("bands array").is_empty(),
            "case {case_id} must carry no band"
        );
        let notes = row["missing_band_notes"].as_array().expect("missing notes");
        assert!(
            notes.len() >= 3,
            "case {case_id}: the missing-band notes must name every band metric"
        );
        let note_metrics: Vec<&str> = notes
            .iter()
            .map(|n| n["metric"].as_str().expect("metric"))
            .collect();
        for metric in ["annual_cooling", "max_zone_temp", "peak_cooling"] {
            assert!(
                note_metrics.contains(&metric),
                "case {case_id}: missing-band note for {metric} is absent"
            );
        }
        for note in notes {
            let text = note["note"].as_str().expect("note");
            assert!(
                text.len() > 60,
                "case {case_id}: a missing-band note must explain the absence"
            );
            assert_eq!(
                note["status"].as_str(),
                Some("no_band"),
                "case {case_id}: missing-band notes are no_band rows"
            );
        }
        assert!(
            !row["comparative_note"].is_null(),
            "case {case_id}: the §9b table's comparative note must be carried"
        );
        // The case is still executed — an unbanded case is not an unexecuted
        // case.
        assert!(
            !row["runs"].as_array().expect("runs").is_empty(),
            "case {case_id} must still be executed through the engine dispatch"
        );
    }
    assert_eq!(
        UNBANDED_CASES.len(),
        5,
        "the bounds file does not cover five of the fourteen CE cases"
    );
}

/// The §9b table's own band edges are used verbatim: the harness never fits
/// or widens a band, and never derives a band for an unbanded case.
#[test]
fn test_section9b_bands_are_read_verbatim() {
    let cases = load_section9b_cases();
    let live = build_results();
    let rows = live["cases"].as_array().expect("cases array");
    for case in &cases {
        let case_id = case["case_id"].as_str().expect("case_id");
        let row = rows
            .iter()
            .find(|r| r["case_id"] == case_id)
            .expect("case row");
        let bands = row["bands"].as_array().expect("bands array");
        for band in case["bands"].as_array().expect("bands array") {
            let metric = band["metric"].as_str().expect("metric");
            let scored = bands
                .iter()
                .find(|b| b["metric"] == metric)
                .unwrap_or_else(|| panic!("case {case_id}: band row for {metric} is missing"));
            assert_eq!(
                scored["band_low"].as_f64(),
                Some(band["recorded_low"].as_f64().expect("recorded_low")),
                "case {case_id}: band low was modified"
            );
            assert_eq!(
                scored["band_high"].as_f64(),
                Some(band["recorded_high"].as_f64().expect("recorded_high")),
                "case {case_id}: band high was modified"
            );
            assert_eq!(
                scored["band_low_si"].as_f64(),
                Some(band["band_low_si"].as_f64().expect("band_low_si")),
                "case {case_id}: SI band low was modified"
            );
            assert_eq!(
                scored["band_high_si"].as_f64(),
                Some(band["band_high_si"].as_f64().expect("band_high_si")),
                "case {case_id}: SI band high was modified"
            );
            assert_eq!(
                scored["band_source"].as_str(),
                band["band_source"].as_str(),
                "case {case_id}: band source was modified"
            );
        }
    }
}

